task apps_3508__halving_sum(n: int) returns (r: int)
  requires n > 0
  ensures r == sum_halves(n)
spec fun sum_halves(n: int): int
  decreases n
= if n <= 0 then 0 else n + sum_halves(n / 2)
{
  r := 0;
  var current: int := n;
  while current > 0
    invariant r == sum_halves(n) - sum_halves(current)
    invariant current >= 0
    decreases current
  {
    r := r + current;
    current := current / 2;
  }
}

